import React, { useState, useRef } from 'react';
import { Link } from 'react-router-dom';
import { PlayIcon, PauseIcon, SpeakerWaveIcon } from '@heroicons/react/24/solid';

interface AudioControls {
  speed: number;
  volume: number;
}

const DocumentUploadPage: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<File | null>(null);
  const [extractedText, setExtractedText] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [showTextSection, setShowTextSection] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string>('');
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [controls, setControls] = useState<AudioControls>({
    speed: 1,
    volume: 1,
  });

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const progressBarRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        alert('Please upload a PDF file');
        return;
      }
      setPdfFile(file);
      setExtractedText('');
      setShowTextSection(false);
    }
  };

  const handleExtractText = async () => {
    if (!pdfFile) {
      alert('Please upload a PDF file first');
      return;
    }

    try {
      setIsLoading(true);
      const formData = new FormData();
      formData.append('file', pdfFile);
      
      const response = await fetch('http://localhost:8000/api/pdf/upload', {
        method: 'POST',
        body: formData,
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to extract text from PDF');
      }
      
      const data = await response.json();
      setExtractedText(data.text);
      setShowTextSection(true);
      console.log('Text extracted successfully:', data);
    } catch (error) {
      console.error('Error extracting text:', error);
      alert(`Error extracting text: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGenerateSpeech = async () => {
    if (!extractedText) {
      alert('Please extract text from the PDF first');
      return;
    }

    const voicePath = localStorage.getItem('voicePath');
    if (!voicePath) {
      alert('No voice model found. Please record your voice first');
      return;
    }

    try {
      setIsLoading(true);
      const response = await fetch('http://localhost:8000/api/pdf/read', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          text: extractedText,
          voice_path: voicePath,
        }),
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to generate speech');
      }
      
      const data = await response.json();
      console.log('Speech generated successfully:', data);
      
      const url = `http://localhost:8000${data.audio_path}`;
      setAudioUrl(url);
      
      // Create new audio element
      const audio = new Audio(url);
      audioRef.current = audio;
      
      // Set up audio event listeners
      audio.onloadedmetadata = () => {
        setDuration(audio.duration);
      };
      
      audio.ontimeupdate = () => {
        setCurrentTime(audio.currentTime);
      };
      
      audio.onended = () => {
        setIsPlaying(false);
        setCurrentTime(0);
      };

    } catch (error) {
      console.error('Error generating speech:', error);
      alert(`Error generating speech: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const togglePlayPause = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        audioRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleProgressBarClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (audioRef.current && progressBarRef.current) {
      const rect = progressBarRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const percentage = x / rect.width;
      const newTime = percentage * duration;
      audioRef.current.currentTime = newTime;
      setCurrentTime(newTime);
    }
  };

  const handleSpeedChange = (speed: number) => {
    if (audioRef.current) {
      audioRef.current.playbackRate = speed;
      setControls(prev => ({ ...prev, speed }));
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const volume = parseFloat(e.target.value);
    if (audioRef.current) {
      audioRef.current.volume = volume;
      setControls(prev => ({ ...prev, volume }));
    }
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      <div className="max-w-4xl mx-auto py-12 px-4">
        <h1 className="text-4xl font-bold text-center mb-12 text-gray-800 drop-shadow-sm">Document Upload</h1>
        
        <div className="bg-white/80 backdrop-blur-sm rounded-xl shadow-lg p-8 border border-gray-100">
          <h2 className="text-2xl font-semibold mb-6 text-gray-800">Upload PDF Document</h2>
          <div className="flex flex-col items-center">
            <button
              onClick={() => document.getElementById('pdf-upload')?.click()}
              className="px-6 py-3 bg-gradient-to-r from-blue-600 to-blue-700 text-white rounded-lg hover:from-blue-700 hover:to-blue-800 transition-all duration-200 mb-4 shadow-md hover:shadow-lg"
            >
              Choose File
            </button>
            <input
              id="pdf-upload"
              type="file"
              accept=".pdf"
              onChange={handleFileUpload}
              className="hidden"
            />
            {pdfFile && (
              <div className="text-gray-600 mt-2 bg-blue-50 px-4 py-2 rounded-lg">
                Selected file: {pdfFile.name}
              </div>
            )}
          </div>
          {pdfFile && !showTextSection && (
            <div className="flex justify-center mt-6">
              <button
                onClick={handleExtractText}
                disabled={isLoading}
                className="px-6 py-3 bg-gradient-to-r from-blue-600 to-blue-700 text-white rounded-lg hover:from-blue-700 hover:to-blue-800 transition-all duration-200 disabled:from-blue-300 disabled:to-blue-400 shadow-md hover:shadow-lg"
              >
                {isLoading ? 'Extracting Text...' : 'Extract Text'}
              </button>
            </div>
          )}
        </div>

        {showTextSection && extractedText && (
          <div className="mt-8 bg-white/80 backdrop-blur-sm rounded-xl shadow-lg p-8 border border-gray-100">
            <h2 className="text-2xl font-semibold mb-6 text-gray-800">Extracted Text</h2>
            <div className="bg-gray-50/80 rounded-lg p-4 mb-6 max-h-60 overflow-y-auto border border-gray-100">
              <p className="text-gray-700 whitespace-pre-wrap">{extractedText}</p>
            </div>
            <div className="flex justify-center">
              <button
                onClick={handleGenerateSpeech}
                disabled={isLoading}
                className="px-6 py-3 bg-gradient-to-r from-green-600 to-green-700 text-white rounded-lg hover:from-green-700 hover:to-green-800 transition-all duration-200 disabled:from-green-300 disabled:to-green-400 shadow-md hover:shadow-lg"
              >
                {isLoading ? 'Generating Speech...' : 'Generate Speech'}
              </button>
            </div>
          </div>
        )}

        {audioUrl && (
          <div className="mt-8 bg-white/80 backdrop-blur-sm rounded-xl shadow-lg p-8 border border-gray-100">
            <div className="flex flex-col space-y-4">
              {/* Audio Player UI */}
              <div className="bg-gradient-to-r from-gray-50 to-gray-100 rounded-full p-4 flex items-center space-x-4 shadow-inner">
                <button
                  onClick={togglePlayPause}
                  className="w-10 h-10 flex items-center justify-center bg-white rounded-full shadow-md hover:shadow-lg transition-all duration-200 hover:bg-gray-50"
                >
                  {isPlaying ? (
                    <PauseIcon className="w-5 h-5 text-blue-600" />
                  ) : (
                    <PlayIcon className="w-5 h-5 text-blue-600" />
                  )}
                </button>

                <div className="flex-1 flex items-center space-x-2">
                  <span className="text-sm text-gray-600 font-medium">{formatTime(currentTime)}</span>
                  <div
                    ref={progressBarRef}
                    className="flex-1 h-2 bg-gray-200 rounded-full cursor-pointer shadow-inner"
                    onClick={handleProgressBarClick}
                  >
                    <div
                      className="h-full bg-gradient-to-r from-blue-500 to-blue-600 rounded-full"
                      style={{ width: `${(currentTime / duration) * 100}%` }}
                    />
                  </div>
                  <span className="text-sm text-gray-600 font-medium">{formatTime(duration)}</span>
                </div>

                <div className="flex items-center space-x-4">
                  {/* Speed Control */}
                  <div className="flex items-center space-x-2">
                    <select
                      value={controls.speed}
                      onChange={(e) => handleSpeedChange(parseFloat(e.target.value))}
                      className="bg-white border border-gray-200 rounded-lg px-2 py-1 text-sm text-gray-700 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 shadow-sm"
                    >
                      <option value={0.5}>0.5x</option>
                      <option value={1}>1x</option>
                      <option value={1.5}>1.5x</option>
                      <option value={2}>2x</option>
                    </select>
                  </div>

                  {/* Volume Control */}
                  <div className="flex items-center space-x-2">
                    <SpeakerWaveIcon className="w-5 h-5 text-blue-600" />
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.1"
                      value={controls.volume}
                      onChange={handleVolumeChange}
                      className="w-20 accent-blue-600"
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="mt-8 flex justify-center">
          <Link
            to="/"
            className="text-blue-600 hover:text-blue-800 font-medium transition-colors duration-200 hover:underline"
          >
            ← Back to Voice Recording
          </Link>
        </div>
      </div>
    </div>
  );
};

export default DocumentUploadPage;
